import{_ as s,o as i,c as a,ai as t}from"./chunks/framework.Ci0kozOl.js";const o="/assets/3.0/images/webhooks-list.png",g=JSON.parse('{"title":"Webhooks","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/packages/webhooks.md","filePath":"3.0/packages/webhooks.md","lastUpdated":1786019473000}'),n={name:"3.0/packages/webhooks.md"};function h(d,e,l,r,p,c){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to &quot;Webhooks&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>Webhooks let UnoPim push product data to your external HTTP endpoints the moment products change, so your storefronts, ERPs, and middleware stay in sync without polling the API. Instead of asking &quot;has anything changed?&quot; every few minutes, your systems simply wait for UnoPim to tell them.</p><p>As of <strong>v3.0</strong>, the single-webhook configuration has grown into a full <strong>multi-webhook module</strong> (<code>Webkul\\Webhook</code>). You may register any number of endpoints, and each one carries its own event subscriptions, an optional HMAC signing secret, custom headers, and scoped delivery logs. For example, you might point one webhook at your Shopify middleware for <code>product.updated</code> events while a second webhook notifies your ERP whenever a product is created.</p><p>If you are upgrading from v2.x, your existing webhook settings are migrated automatically — the legacy URL becomes the first <code>webhooks</code> row, subscribed to both product events, and your old logs are attached to it.</p><p><img src="'+o+`" alt="Multi-webhook configuration in the UnoPim admin"></p><h2 id="managing-webhooks-in-the-admin" tabindex="-1">Managing Webhooks in the Admin <a class="header-anchor" href="#managing-webhooks-in-the-admin" aria-label="Permalink to &quot;Managing Webhooks in the Admin&quot;">​</a></h2><p>You may manage webhooks from <strong>Configuration → Webhook</strong>. The routes live under <code>admin/configuration/webhook</code> (named <code>webhook.*</code>) and provide the full CRUD, mass delete, and a <strong>Test</strong> action that POSTs a <code>webhook.test</code> payload to your endpoint with a 10-second timeout, so you can confirm connectivity before going live.</p><p>Delivery logs have their own routes (<code>webhook.logs.*</code> — list, per-webhook scope, detail, delete, and mass delete). Access is gated by the ACL keys <code>configuration.webhook[.create|.edit|.delete]</code> and <code>configuration.webhook.logs[.view|.delete|.mass_delete]</code>.</p><h2 id="how-delivery-works" tabindex="-1">How Delivery Works <a class="header-anchor" href="#how-delivery-works" aria-label="Permalink to &quot;How Delivery Works&quot;">​</a></h2><p>Deliveries run asynchronously on the <strong><code>webhooks</code> queue</strong>. Single changes are dispatched via <code>SendProductWebhook</code> (<code>$tries = 3</code>, <code>$backoff = 30</code>), while bulk operations use <code>SendBulkProductWebhook</code> and <code>SendBulkEditProductWebhook</code>. Batches are chunked at 100 products per request, so even large imports produce a manageable stream of calls.</p><p>Each request carries a set of headers, built by <code>WebhookService::buildHeaders()</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>X-Unopim-Event:      product.updated</span></span>
<span class="line"><span>X-Unopim-Webhook-Id: 42</span></span>
<span class="line"><span>X-Unopim-Signature:  sha256=&lt;hmac&gt;        # only when a secret is set</span></span>
<span class="line"><span>...plus any custom headers configured on the webhook</span></span></code></pre></div><p>A single-event payload looks like this:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;event&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;product.updated&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;timestamp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-08-04 10:00:00&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;user_timezone&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Asia/Kolkata&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;sku&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;shirt-1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;simple&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;changes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;added&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {}, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;removed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {}, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;changed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {} } }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Configurable products additionally carry <code>variants: [{sku, status}]</code>. UnoPim detects changes by diffing the latest audit record via <code>ProductComparer</code>, and it will automatically skip delivery when nothing meaningful changed.</p><h2 id="verifying-signatures" tabindex="-1">Verifying Signatures <a class="header-anchor" href="#verifying-signatures" aria-label="Permalink to &quot;Verifying Signatures&quot;">​</a></h2><p>When you configure a secret on a webhook, UnoPim signs every request so your receiver can be sure the payload really came from your PIM. The signature is <code>hash_hmac(&#39;sha256&#39;, $exactJsonBody, $secret)</code> computed over the exact body sent — you should verify it before trusting a payload.</p><p>Leaving the secret field blank when updating a webhook never wipes an existing secret, so you may safely edit other fields without re-entering it.</p><h2 id="ssrf-protection" tabindex="-1">SSRF Protection <a class="header-anchor" href="#ssrf-protection" aria-label="Permalink to &quot;SSRF Protection&quot;">​</a></h2><p>Because webhook URLs are user-supplied, every URL passes through <code>Webkul\\Webhook\\Validators\\SafeWebhookUrl</code> at both save time and delivery time. Only http/https schemes are allowed, the hostname is DNS-resolved, private, reserved, link-local, and multicast addresses are rejected, redirects are disabled, and the connection is pinned to the validated IP (<code>CURLOPT_RESOLVE</code>) to defeat DNS rebinding.</p><p>Sometimes during local development you may wish to deliver to a loopback target. This is an explicit opt-in:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">WEBHOOK_ALLOW_LOOPBACK</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">true</span></span></code></pre></div><h2 id="pruning-delivery-logs" tabindex="-1">Pruning Delivery Logs <a class="header-anchor" href="#pruning-delivery-logs" aria-label="Permalink to &quot;Pruning Delivery Logs&quot;">​</a></h2><p>Delivery logs accumulate quickly on a busy catalog, so UnoPim ships a pruning command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> webhook:logs:prune</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--days=30]</span></span></code></pre></div><p>This deletes delivery logs older than the retention window (<code>WEBHOOK_LOG_RETENTION_DAYS</code>, default 30; setting it to <code>0</code> disables pruning). The package&#39;s service provider schedules the command to run daily, so you rarely need to invoke it by hand.</p><h2 id="registering-custom-events" tabindex="-1">Registering Custom Events <a class="header-anchor" href="#registering-custom-events" aria-label="Permalink to &quot;Registering Custom Events&quot;">​</a></h2><p>The event catalog is a container singleton, <code>Webkul\\Webhook\\Registry\\EventRegistry</code>, seeded from the <code>webhook.events</code> config. If your package wants to expose its own webhook events, you may register them either through the facade or by merging config:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// In your service provider&#39;s boot():</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">use</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Webkul\\Webhook\\Facades\\WebhookEvent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">WebhookEvent</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">register</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;order&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;order.created&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;shop::app.webhook-events.order.created&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Or merge config: return [&#39;events&#39; =&gt; [&#39;order&#39; =&gt; [...]]];</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$this</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mergeConfigFrom</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">__DIR__</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/../Config/webhook.php&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;webhook&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>The admin form&#39;s event multiselect, the <code>in:</code> validation rule, and the log columns will automatically pick up your new keys. Your package then dispatches delivery itself — typically a listener that queues a job calling <code>WebhookRepository::getActiveForEvent($key)</code> and <code>WebhookService</code>-style delivery.</p><h2 id="upgrading-from-the-single-webhook" tabindex="-1">Upgrading From the Single Webhook <a class="header-anchor" href="#upgrading-from-the-single-webhook" aria-label="Permalink to &quot;Upgrading From the Single Webhook&quot;">​</a></h2><p>The v3.0 migration reads the legacy <code>webhook_settings</code> rows, creates a <code>webhooks</code> row from the configured URL (subscribed to <code>product.created</code> + <code>product.updated</code>, with the active flag preserved), and re-parents orphaned logs. The migration is idempotent, and rolling back removes only the seeded row.</p><div class="warning custom-block"><p class="custom-block-title">Removed classes</p><p><code>WebhookSettingsController</code> and the old <code>SettingsRepository</code> no longer exist. Extensions must use <code>WebhookRepository</code> and the <code>webhooks</code> model.</p></div><h2 id="data-model" tabindex="-1">Data Model <a class="header-anchor" href="#data-model" aria-label="Permalink to &quot;Data Model&quot;">​</a></h2><p>Two tables back the module:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>webhooks       name, url, is_active, events (json), secret, headers (json), extra</span></span>
<span class="line"><span>webhook_logs   webhook_id (nullOnDelete), sku, event, user, status, http_code, extra</span></span></code></pre></div><p>The model excludes <code>secret</code> from audit history (<code>$auditExclude</code>), and delivery logs are indexed on <code>[webhook_id, created_at]</code> and <code>[status, created_at]</code> to keep the log grids fast.</p><p><code>Webkul\\Webhook\\Repositories\\WebhookRepository</code> is the query surface you should build against:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$repository</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getActiveForEvent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;product.updated&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// is_active + whereJsonContains(&#39;events&#39;, ...)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$repository</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hasActiveForEvent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;product.created&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><h2 id="built-in-events" tabindex="-1">Built-In Events <a class="header-anchor" href="#built-in-events" aria-label="Permalink to &quot;Built-In Events&quot;">​</a></h2><p>Out of the box, UnoPim ships two webhook events, <code>product.created</code> and <code>product.updated</code>, fired from the following platform events:</p><table tabindex="0"><thead><tr><th>Platform event</th><th>Webhook event</th></tr></thead><tbody><tr><td><code>catalog.product.create.after</code></td><td><code>product.created</code></td></tr><tr><td><code>catalog.product.update.after</code></td><td><code>product.updated</code></td></tr><tr><td><code>catalog.product.bulk.edit.after</code></td><td><code>product.updated</code> (batch)</td></tr><tr><td><code>data_transfer.imports.batch.product.created.after</code></td><td><code>product.created</code> (batch)</td></tr><tr><td><code>data_transfer.imports.batch.product.updated.after</code></td><td><code>product.updated</code> (batch)</td></tr></tbody></table>`,43)])])}const u=s(n,[["render",h]]);export{g as __pageData,u as default};
